+    /**
+     * Returns the total number of customers matching the given filters.
+     *
+     * @param nameFilter whitespace-separated terms that must all appear in firstName or lastName
+     * @param statusFilter list of statuses to match; if empty, all statuses match
+     * @implNote every call is recorded in {@link QueryLog}
+     */
+    public int count(String nameFilter, List<CustomerStatus> statusFilter) {
+        int total = (int) customers.stream()
+                .filter(c -> matchesFilters(c, nameFilter, statusFilter))
+                .count();
+        queryLog.recordCount(total);
+        return total;
+    }
+
+    private static boolean matchesFilters(Customer c, String nameFilter, List<CustomerStatus> statusFilter) {
+        if (!matchesNameFilter(c, nameFilter)) {
+            return false;
+        }
+        if (!statusFilter.isEmpty() && !statusFilter.contains(c.status())) {
+            return false;
+        }
+        return true;
+    }
+
+    private static boolean matchesNameFilter(Customer c, String nameFilter) {
+        if (nameFilter == null || nameFilter.isBlank()) {
+            return true;
+        }
+        String[] terms = nameFilter.trim().split("\\s+");
+        String fullName = (c.firstName() + " " + c.lastName()).toLowerCase(Locale.ROOT);
+        Collator collator = Collator.getInstance();
+        collator.setStrength(Collator.PRIMARY);
+        for (String term : terms) {
+            if (!containsTermIgnoreAccents(fullName, term.toLowerCase(Locale.ROOT), collator)) {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    private static boolean containsTermIgnoreAccents(String text, String term, Collator collator) {
+        for (int i = 0; i <= text.length() - term.length(); i++) {
+            if (collator.equals(text.substring(i, i + term.length()), term)) {
+                return true;
+            }
+        }
+        return false;
+    }
+
